    """amount * (100 - pct) / 100, rounded half up to a whole cent, in exact integer arithmetic."""
    if amount < 0:
        raise RuntimeError(f"negative amount {amount}")
    q, r = divmod(amount * (100 - pct), 100)
    return q + 1 if r >= 50 else q


def discounted_cents_decimal(amount, pct):
    """Independent cross-check of discounted_cents."""
    value = Decimal(amount) * (Decimal(100) - Decimal(pct)) / Decimal(100)
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def main():
    api = Api()

    # Pages: fetch every page by number, then check each page's own metadata.
    first = api.get("/orders?page=1")
    total_pages = first["total_pages"]
    pages = {1: first}
    for n in range(2, total_pages + 1):
        pages[n] = api.get(f"/orders?page={n}")
    log(f"fetched {len(pages)} pages; total_pages reported as {total_pages}")

    for n, page in pages.items():
        expected_next = f"/orders?page={n + 1}" if n < total_pages else None
        items = page.get("items")
        problems = []
        if page.get("page") != n:
            problems.append(f"page field is {page.get('page')!r}")
        if page.get("total_pages") != total_pages:
            problems.append(f"total_pages is {page.get('total_pages')!r}")
        if page.get("next") != expected_next:
            problems.append(f"next is {page.get('next')!r}")
        if not isinstance(items, list):
            problems.append("items is not a list")
        elif n < total_pages and len(items) != PAGE_SIZE:
            problems.append(f"{len(items)} items on a non-final page")
        if problems:
            raise RuntimeError(f"page {n}: " + "; ".join(problems))
        with open(os.path.join(SCRATCH, "raw", f"page-{n:02d}.json"), "w") as f:
            json.dump(page, f)

    listings = [(n, item) for n in sorted(pages) for item in pages[n]["items"]]
    for n, item in listings:
        if not isinstance(item, dict) or set(item) != ITEM_KEYS:
            raise RuntimeError(f"page {n}: unexpected item shape {item!r}")
        for key in ("id", "customer_id", "status", "placed_at"):
            if not isinstance(item[key], str):
                raise RuntimeError(f"page {n}: {key} is not a string in {item!r}")
        if not isinstance(item["amount_cents"], int) or isinstance(item["amount_cents"], bool):
            raise RuntimeError(f"page {n}: amount_cents is not an integer in {item!r}")
    log(f"{len(listings)} listings across all pages")

    # Duplicates: keep the first listing of each id; every later listing of the same id is discarded.
    first_listing = {}
    duplicates = []
    for n, item in listings:
        if item["id"] in first_listing:
            first_page, original = first_listing[item["id"]]
            duplicates.append((item["id"], first_page, n, original == item))
        else:
            first_listing[item["id"]] = (n, item)
    distinct = [item for _, item in first_listing.values()]
    not_identical = [d for d in duplicates if not d[3]]
    log(f"{len(distinct)} distinct order ids; {len(duplicates)} repeated listings discarded")
    if not_identical:
        log(f"WARNING: {len(not_identical)} repeated listings differ from their first copy: {not_identical[:5]}")
    log(f"statuses across distinct orders: {dict(Counter(item['status'] for item in distinct))}")

    # Timestamps: every distinct order must parse, with an offset, before any filtering.
    placed = {item["id"]: parse_utc(item["placed_at"]) for item in distinct}

    qualifying = [
        item for item in distinct
        if item["status"] == "shipped" and RANGE_START <= placed[item["id"]] < RANGE_END
    ]
    log(f"{len(qualifying)} shipped orders placed 1 Mar - 31 May 2025 (UTC)")

    # Customers: look each one up once, keep the record for every later order.
    customers = {}
    for cid in sorted({item["customer_id"] for item in qualifying}):
        rec = api.get(f"/customers/{cid}")
        with open(os.path.join(SCRATCH, "raw", f"customer-{cid}.json"), "w") as f:
            json.dump(rec, f)
        pct = rec.get("discount_pct")
        if (rec.get("id") != cid or rec.get("region") not in REGIONS
                or not isinstance(pct, int) or isinstance(pct, bool) or not 0 <= pct <= 100):
            raise RuntimeError(f"customer {cid}: unexpected record {rec!r}")
        customers[cid] = rec
    log(f"looked up {len(customers)} customers, once each")

    # Totals: round each order on its own, then sum.
    by_region = {region: 0 for region in REGIONS}
    total = 0
    for item in qualifying:
        cust = customers[item["customer_id"]]
        cents = discounted_cents(item["amount_cents"], cust["discount_pct"])
        if cents != discounted_cents_decimal(item["amount_cents"], cust["discount_pct"]):
            raise RuntimeError(f"rounding cross-check failed for {item['id']}")
        total += cents
        by_region[cust["region"]] += cents
    if sum(by_region.values()) != total:
        raise RuntimeError("by_region does not sum to total_cents")

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": len(duplicates),
        "by_region": by_region,
    }
    with open(RESULT_PATH, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    log(f"wrote {RESULT_PATH}: {json.dumps(result)}")
    log(f"api counts: {api.counts}")


if __name__ == "__main__":
    main()
